        '<b>서울시가 이미 내준 것.</b> 일반주거지역을 상업지역으로 바꿔주고 용적률(대지면적 대비 지을 수 있는 총 바닥면적의 비율)을 900%가 넘게 올려줬다. 대신 늘어난 용적률의 60%를 공공기여(개발 이익 일부를 도로·공원 같은 시설로 내놓는 것)로 받았고 규모가 6천억 원대다. 성수대교 램프와 용비교 램프를 새로 놓고 입체 보행공원을 만든다.',
        '<b>왜 국토부까지 보나.</b> 수도권정비계획법이다. 1982년에 사람과 공장이 수도권에 몰리는 것을 막자고 만든 법으로 서울은 과밀억제권역이다. 공장·학교·공공청사 같은 <b>인구집중유발시설</b> 다섯 가지가 빠져나간 자리에 다시 큰 복합시설이 들어오면 국토부 심의를 받아야 한다. 아파트 자리에 아파트를 짓는 재건축은 해당되지 않는다.',
        '<b>보류 사유 원문.</b> "한정된 서울의 토지 자원을 이용한 초고가 주택, 6성급 호텔 같은 하이엔드 개발 계획이 공공복리 목적에 부합하는지 명확히 소명할 것." 무엇을 고치라고는 적지 않았고 수정안을 가져오라고만 했다.',
        '<b>같은 단어를 두 기관이 다르게 쓴다.</b> 국토부 쪽은 실수요자가 접근할 수 있는 주택을 많이 공급하고 인구 집중을 억제하는 것이 공공복리라고 본다. 서울시 쪽은 용도변경과 용적률의 대가로 6천억 원을 받아 교통망을 고치고 업무·호텔로 지역을 개발하는 것이 공공복리라고 본다.',
        '<b>주변이 이미 그런 동네다.</b> 서울숲 트리마제의 큰 평형(약 300㎡)이 170억 원, 아크로 서울포레스트가 최대 300억 원까지 호가가 붙어 있다. 갤러리아 포레도 100평대가 모여 있다. 그래서 사업자는 비슷한 급으로 계획을 짜 왔고 서울시도 무리가 없다고 봤다.',
        '<b>고치기가 쉽지 않다.</b> 84㎡(국민주택 규모)를 넣는 설계 변경을 검토한다는 이야기가 나오지만 설계가 이미 다 나온 상태다. 층수를 낮추거나 평형을 줄이면 랜드마크라는 상징성이 흔들리는데, 이 사업장에서는 그 상징성이 곧 분양가라 사업성과 직결된다.',
        '<b>선례는 GBC다.</b> 강남 한전 부지도 공공기관이 나간 자리라 같은 심의를 받았고 2017~2018년에 <b>세 번 연속 반려</b>됐다. 정부가 기업 투자 활성화 기조를 밝히고 사업자가 상업시설 배치를 손보면서 조건부로 통과됐다. 105층 한 동이던 계획은 49~55층 세 개 동이 됐다. 같은 법, 같은 위원회인데 정권 기조에 따라 결과가 달라진 셈이다.',
        '<b>81층에는 군의 청구서가 붙는다.</b> 서울 전역이 대공방어협조구역이라 동네에서 가장 높은 건물 옥상에는 대공포가 올라간다. 군은 포만 가져오고 <b>기초 시공·막사·사무실은 시행자 부담</b>이며 연병장이나 전용 엘리베이터를 요구하는 경우도 있다. 수십억에서 수백억 원이 들 수 있다.',
