        '<b>토지거래허가 실무에 함정.</b> 부동산거래신고법은 허가 전 계약을 무효로 보는데 실무는 가계약금을 넣고 허가를 신청한다. 2월 10일부터 자금조달계획서에 <b>계약금 지급 증빙</b>을 붙이게 되면서 입금일과 신청일이 나란히 드러난다. 담당 주무관이 돈을 돌려주고 다시 신청하라 한 사례가 있다.',
