        '<b>한국 종부세(종합부동산세, 비싼 집에 재산세와 별도로 더 매기는 세금)만 두 가지가 특이하다.</b> 국세(중앙정부가 걷는 세금)로 걷어 교부금(중앙정부가 지방에 나눠주는 돈)으로 전국에 재배분하고(50% 이상이 서울에서 걷힌다), 시장 안정을 목적에 넣었다. 다른 도시 보유세에는 그 목적 자체가 없다. 굳이 시장을 잡으려면 취득세와 양도세로 한다.',
        '<b>세수 비중이 성격을 말한다.</b> 뉴욕과 LA는 세수의 40% 이상이 보유세라 없으면 도시가 안 굴러간다. 치안과 공립학교의 질이 여기 직결된다. 도쿄는 28%, 서울 재산세는 15%뿐이다.',
        '<b>과세 기준도 제각각.</b> 런던은 1991년 시점 가치로 밴드(가격대별 구간)를 나누고 위에 캡(상한)을 둔다. 그래서 비싼 집일수록 값 대비 부담이 낮은 역진 구조다. LA는 취득가(집을 산 값) 기준이고, 뉴욕 콘도와 싱가포르는 임대 가치로 환산한다. 서울과 도쿄는 공시가(정부가 매년 매기는 기준 가격)를 쓴다.',
        '<b>런던은 거주자가 낸다.</b> 집주인이 아니라 사는 사람이 내므로 세입자 부담이다. 순수 서비스 요금이고 부유세 성격이 0에 가깝다. 대신 비워둔 세컨드 홈에는 페널티가 붙는다.',
        '<b>다주택 중과는 한국뿐이다.</b> 미국에서 두세 채는 다주택 취급도 하지 않는다. 규제 논의 대상은 수백 채를 가진 기관투자자다. 도쿄는 버블 직후 종부세의 원형인 지가세를 도입했다가, 집값이 내려가는데 세금까지 내라는 반발로 폐지하고 완전 응익 단일세율로 돌아섰다.',
        '<b>싱가포르의 칼은 취득세에 있다.</b> 외국인 60%, 2주택 20%, 3주택 30%를 더 물리고 3년 안에 팔면 매도가 기준으로 벌금성 세금을 매긴다. 보유세 자체는 한국보다도 낮다. 자가보유율 90%에 공공주택 거주 77%라 무겁게 매길 수가 없다.',
        '<b>핵심 실험.</b> 세율을 비교하는 대신 서울 아파트 가격을 그대로 다른 도시 세제에 대입했다. 2025년 실거래가 기준으로 중위 10.5억, 상위25% 15.5억, 상위10% 23억이다.',
        '<b>1주택 결과.</b> 서울 10.5억은 100만 원쯤이고(재산세만), 23억은 481만 원이다. 같은 23억 집이 뉴욕이면 1,000만 원을 넘고 LA면 1,700만 원을 넘는다. 다만 배율로 보면 상위10%가 약 4배인데 중위는 LA 대비 약 8배로 중위 격차가 더 크다. 다른 나라는 누진(비쌀수록 세율이 올라가는 구조)이 없어서다.',
        '<b>3주택이 결과를 뒤집는다.</b> 서울은 1주택에서 3주택으로 가면 10배로 뛴다. 23억을 세 채 가지면 5,000만 원쯤이다. 누진 없는 도시는 그냥 3배다.',
        '<b>소득 대비로도 같다.</b> 서울 중위 소득 6,500만 원 가구가 중위 아파트를 가지면 보유세가 소득의 1.6%, 상위10%면 4%쯤이다. 그런데 3주택 상위10%는 소득의 50%다. 뉴욕은 최대 25%, 상위 소득이면 22%다.',
