        ('전망의 전제가 곧 리스크다', '2028~2029년에 숨통이 트인다는 전망은 정비사업이 순탄하게 굴러간다는 가정 위에 선다. 그런데 같은 방송에서 이주비 대출 차단과 재초환, PF 금리를 리스크로 든다. <b>전제와 리스크가 정면으로 부딪히는데 어느 쪽이 우세한지는 판정하지 않는다.</b>'),
