        '<b>안전 — 자리를 서로 피한다.</b> 중대재해처벌법 이후 현장소장과 감리단장(공사가 설계대로 되는지 감독하는 팀의 책임자)을 구속된다는 이유로 기피하는데 그 자리 수당이 그만큼 오르지는 않는다. 최 교수는 리소스를 아무리 넣어도 사고를 100% 막을 수는 없다며, 의무를 다해도 처벌 대상이 되는 구조를 짚는다.',
        '<b>그게 어떻게 원가가 되나.</b> 안전벨트를 매면 하루 미장(벽에 시멘트를 발라 면을 고르는 작업)이 10제곱미터에서 8제곱미터로 줄고, 벨트 매라고 지키는 사람이 두세 명 붙고, CCTV 사각지대 때문에 전 직원이 경찰용 바디캠을 차고 돌아다닌다. 결과가 공사 기간 40개월에서 50개월이다.',
        '<b>불만은 안전 강화가 아니라 책임 배분이다.</b> 원청(공사를 통째로 맡아 하도급을 주는 회사)에만 너무 가혹하고, 불안전한 행동을 한 작업자에게도 불이익이 가야 같이 움직인다고 말한다. 무사고 보너스 1억을 줘도 사고는 똑같이 난다고 보는데, 관리와 감독만으로는 안 되고 작업자 안전 의식이 같이 와야 한다는 뜻이다.',
        '<b>숙련공 — 물 쓰는 공정이 통째로 비었다.</b> 미장과 조적(벽돌을 한 장씩 쌓는 것), 타일은 눈을 씻고 찾아봐도 없고 한국인 숙련공은 60대가 안 보이고 70대는 돼야 보인다. 외국인 근로자가 반장과 조장까지 한다. 여기에 52시간이 겹쳐 숙련 기사가 6시에 퇴근하면 그 팀 작업도 끝난다.',
        '<b>대응은 건식공법(물을 안 쓰고 자재를 조립해 붙이는 방식)과 PC(프리캐스트 콘크리트, 공장에서 미리 찍어 오는 부재)다.</b> 조적을 없애고 석고보드에 차음재를 넣고, 마지막까지 시멘트 벽돌이 남아 있던 욕실 벽도 건식으로 갔다. 다만 PC도 조인트는 현장에서 레미콘을 타설해야 하고, 난방배관 위 방통 미장(배관 위에 시멘트를 부어 덮는 공정)과 배수구 쪽 구배(물이 흐르도록 잡는 기울기)를 잡는 욕실 바닥은 습식과 숙련공이 남는다.',
        '<b>왜 안 배우나.</b> 이 편에서 가장 비직관적인 대목이다. 몸값이 오를수록 불안해진다. 골칫거리였던 옥탑이 PC로 찍어 올리는 방법이 개발되며 그 일이 사라진 전례가 있다. 일당 25만 원이면 남지만 70만 원이 되는 순간 기계가 대체하므로, 연봉이 올라도 진입하지 않는다.',
        '<b>규정 — 단열재 하나가 연쇄를 만든다.</b> 20~30년 전 50mm면 됐던 내단열이 지금 150mm쯤 된다. 그러면 창틀이 그만큼 안쪽으로 나와 허공에 뜨고, 쇠로 45도 받쳐야 하고, 그 쇠를 타고 냉기가 들어와 거기에 또 단열을 해야 한다. 열교환 환기도 고급 옵션에서 전 세대 의무가 되며 굵은 덕트가 천장을 채웠다.',
        '<b>초고층은 절대 싸질 수 없다.</b> 기준은 50층 또는 200m다. 진짜 문제는 풍하중(바람이 건물을 미는 힘)이다. 위에서 누르는 힘은 한 방향이라 기둥과 보로 풀 수 있지만 바람은 어디서 불지 몰라 사방팔방을 보강해야 한다. 피난안전구역(불이 났을 때 대피해 버티는 층)은 한 층을 통째로 비우고 헬스 기구도 못 놓는다. 시간이 지나 싸질 가능성은 단 1도 없다는 게 그의 말이다.',
        '<b>그래서 200m를 피한다.</b> 아크로 서울포레스트가 199.98m다. 2cm 낮춘 200m다. 나 같으면 20cm를 뺀다는 진행자에게 최 교수는 2cm도 맞출 수 있다고 답한다.',
        '<b>재건축 셈이 안 맞는다.</b> 이 편의 진짜 결론이다. 용적률 300%를 재건축하려면 600~700%는 줘야 일반분양으로 공사비가 나오는데 그러려면 60~80층이 필요하고, 그 공사비가 지금 20~30층 수준으로 내려오지 않는다. 이미 50~60층인 초고층은 그 자리에 100층을 올릴 수 없어 경제성 자체가 성립하지 않는다.',
        '<b>재건축을 하는 진짜 이유는 콘크리트가 아니다.</b> 한국 콘크리트도 100년 간다. 바꿔야 하는 건 배관과 전선이고, 실제로는 지하주차장이 없다거나 네 식구인데 화장실이 하나라는 생활 기준 변화가 재건축을 부른다. 리모델링으로는 2베이가 4베이가 되지 못한다.',
        '<b>장수명 주택, 갈림길은 화장실이다.</b> 수직 입상관은 PD(파이프 덕트, 배관만 지나가는 별도 공간)에 있어 이미 교체할 수 있고, 문제는 변기와 세면대, 욕조 배관이 슬래브(층과 층을 나누는 콘크리트 바닥판)를 뚫고 아래층 천장으로 내려간다는 데 있다. 장수명은 이걸 벽으로 돌린다. 미국이나 코스트코 화장실의 바닥에 떠 있는 배관이 그것이다. 재건축 없이 리모델링만으로 배관 교체가 끝난다.',
        '<b>층하로 지은 게 비합리였던 건 아니다.</b> 30~40cm 낙차 덕에 잘 빠지고 하자가 적었고 짓기도 쉬워 80~90년대 대량 공급에 안성맞춤이었다. 일본은 우리 집 시설이 남의 집에 피해를 줄 수 없다는 감각으로 이미 층상으로 전환했다.',
        '<b>막는 건 30%다.</b> 장수명은 초기 공사비가 30%쯤 비싸 분양가만 오르니 아무도 안 고른다. 최 교수는 정부의 강제성이 필요하다고 하고 진행자는 내 임기 문제도 아닌데 표가 되겠냐고 받는다. 결론은 이렇다. "안 짓고 있으니 나중엔 일대일 재건축인데, 그 공사비를 어떻게 하실지는 나도 모르겠다."',
        '<b>곁가지 — 왜 수십 년간 2베이만 지었나.</b> 뚱뚱한 평면이 가운데 벽으로 하중을 받아 구조적으로 싸다. 4베이는 창과 벽량, 단열재, 마감과 슬래브 하중이 다 늘어 비싸다. 아이디어가 없어서가 아니라 대량 공급에 불리해서 안 쓴 것이고, 뒤집은 건 발코니 확장 합법화다. 30평 같은 25평을 팔 수 있고 확장이 건설사 옵션 수익이 되니 4베이가 급증했다.',
        '<b>미래 기술 셋.</b> BIM(빌딩 인포메이션 모델링, 건축·설비·전기 도면을 하나로 합친 3차원 설계)은 중앙 서버 도면 하나를 전 분야가 같이 봐서, 건축이 3년 전에 키운 보를 설비가 몰라 공사 중에 터지던 일이 사라진다. 다만 현장에서는 "BIM 15범"이라 불릴 만큼 안 쓴다. PC와 모듈러는 방을 통째로 만들어 쌓는 데까지 간다. 드론과 AI는 레미콘 5시 출하 마감 전에 눈대중으로 정하던 타설 물량과 덤프 대수, 철근 결속 50% 규정 검측까지 맡을 수 있다.',
