def upload_date(card):
    """카드 meta의 '업로드 2026-08-04'에서 날짜를 뽑는다 — 정렬 기준을 따로 적지 않는다"""
    for m in card['meta']:
        hit = re.search(r'업로드\s*(\d{4}-\d{2}-\d{2})', m)
        if hit:
            return hit.group(1)
    raise ValueError('업로드 날짜가 없는 카드: ' + card['title'])


# 섹션 순서는 손으로 정한다. 여기 없는 섹션은 뒤에 붙고 그들끼리는 최신 편 순이다
SEC_ORDER = ['sec-cluster', 'sec-land', 'sec-tax', 'sec-supply', 'sec-lease', 'sec-permit', 'sec-fight', 'sec-build']


def by_upload_desc(cards):
    """섹션 순서는 SEC_ORDER, 섹션 안 카드는 발행일 최신순. 번호는 최종 순서로 다시 매긴다"""
    newest = {}
    for c in cards:
        sid = c['section'][0]
        newest[sid] = max(newest.get(sid, ''), upload_date(c))
    rest = [sid for sid, _ in sorted(newest.items(), key=lambda kv: kv[1], reverse=True)
            if sid not in SEC_ORDER]
    order = [sid for sid in SEC_ORDER if sid in newest] + rest
    rank = {sid: i for i, sid in enumerate(order)}
    ordered = sorted(cards, key=lambda c: (rank[c['section'][0]], [-ord(ch) for ch in upload_date(c)]))
    num, seen, out = 0, {}, []
    for c in ordered:
        sid, sec = c['section'][0], c['section']
        if sid not in seen:
            num += 1
            seen[sid] = '%02d' % num
        c = dict(c)
        c['section'] = (sec[0], seen[sid], sec[2], sec[3])
        out.append(c)
    return out


# 국내·국외 필터. 다루는 시장이 어디인가로 나눈다 — 비교 대상이 해외여도 질문이 한국 시장이면 국내다
INTL = {'일본에서 땅값이 오르는 지방은 전부 기업을 끼고 있다',
        '싱가포르 자가보유율 90%를 만든 세 축'}
for _c in CARDS:
    _c['scope'] = 'intl' if _c['title'] in INTL else 'kr'

CARDS = by_upload_desc(CARDS)

